INSERT INTO messages (
    conversation_id, whatsapp_message_id, direction,
    sender_type, message_type, text_body, metadata
)
VALUES (
    $1, $2, 'incoming', 'customer', 'text', $3::text, jsonb_build_object('event', $4, 'phone', $5, 'customer_name', $6, 'timestamp', $7, 'hasMedia', $8)
)
ON CONFLICT (whatsapp_message_id)
DO NOTHING
RETURNING id;

INSERT INTO audit_logs (
    entity_type, entity_id, action, performed_by,
    performed_by_type, description, new_values, metadata
)
VALUES (
    'conversation', $1, 'message_received', NULL,
    'system', 'Incoming WhatsApp message received', $2::jsonb,
    jsonb_build_object('source', 'whatsapp', 'workflow', 'Webhook 1')
)
RETURNING id;
